static size_t Qiniu_Section_Read(void *buf, size_t unused, size_t n, Qiniu_Section *self)
{
	Qiniu_Int64 max = 0;
	ssize_t readBytes = 0;
	if (self->limit <= self->off)
	{
		return 0;
	}
	max = self->limit - self->off;
	if ((Qiniu_Int64)n > max)
	{
		n = max & (~(size_t)0L);
	}
	readBytes = self->r.ReadAt(self->r.self, buf, n, self->off);
	if (readBytes < 0)
	{
		n = 0;
	}
	else
	{
		n = (size_t)readBytes;
	}
	self->off += n;
	return n;
}

Qiniu_Reader Qiniu_SectionReader(Qiniu_Section *self, Qiniu_ReaderAt r, Qiniu_Off_T off, size_t n)
{
	Qiniu_Reader ret = {self, (Qiniu_FnRead)Qiniu_Section_Read};
	self->r = r;
	self->off = off;
	self->limit = off + n;
	return ret;
}

/*============================================================================*/
/* type Qiniu_Tee */

static size_t Qiniu_Tee_Read(void *buf, size_t unused, size_t n, Qiniu_Tee *self)
{
	size_t nr = self->r.Read(buf, unused, n, self->r.self);
	if (nr > 0)
	{
		return self->w.Write(buf, unused, nr, self->w.self);
	}
	return nr;
}

Qiniu_Reader Qiniu_TeeReader(Qiniu_Tee *self, Qiniu_Reader r, Qiniu_Writer w)
{
	Qiniu_Reader ret = {self, (Qiniu_FnRead)Qiniu_Tee_Read};
	self->r = r;
	self->w = w;
	return ret;
}

/*============================================================================*/
/* type Qiniu_File */

Qiniu_Error Qiniu_File_Open(Qiniu_File **pp, const char *file)
{
	Qiniu_Error err;
	Qiniu_Posix_Handle fd = Qiniu_Posix_Open(file, O_BINARY | O_RDONLY, 0644);
	if (fd != Qiniu_Posix_InvalidHandle)
	{
		err = Qiniu_OK;
		*pp = (Qiniu_File *)(size_t)fd;
	}
	else
	{
		err.code = errno;
		err.message = "open file failed";
	}
	return err;
}

#if defined(_MSC_VER)

