int Qiniu_Posix_Fstat(Qiniu_Posix_Handle fd, Qiniu_FileInfo *fi)
{
	int ret = 0;
	Emu_FileInfo fi2;

	Qiniu_Zero(fi2);
	ret = Qiniu_Posix_Fstat2(fd, &fi2);
	if (ret < 0)
	{
		return ret;
	}

	fi->st_size = (Qiniu_Off_T)fi2.st_size;
	fi->st_atime = fi2.st_atime;
	fi->st_mtime = fi2.st_mtime;
	fi->st_ctime = fi2.st_ctime;
	return 0;
}

#endif

Qiniu_Error Qiniu_File_Stat(Qiniu_File *self, Qiniu_FileInfo *fi)
{
	Qiniu_Error err;
	if (Qiniu_Posix_Fstat((Qiniu_Posix_Handle)(size_t)self, fi) != 0)
	{
		err.code = errno;
		err.message = "fstat failed";
	}
	else
	{
#if defined(__APPLE__) && defined(TARGET_OS_MAC)
		fi->st_size >>= 32;
#endif
		err = Qiniu_OK;
	}
	return err;
}

void Qiniu_File_Close(void *self)
{
	Qiniu_Posix_Close((Qiniu_Posix_Handle)(size_t)self);
}

ssize_t Qiniu_File_ReadAt(void *self, void *buf, size_t bytes, Qiniu_Off_T offset)
{
	return Qiniu_Posix_Pread((Qiniu_Posix_Handle)(size_t)self, buf, bytes, offset);
}

Qiniu_ReaderAt Qiniu_FileReaderAt(Qiniu_File *self)
{
	Qiniu_ReaderAt ret = {self, Qiniu_File_ReadAt};
	return ret;
}

