22: Qiniu_Bool Qiniu_Utils_Extract_Bucket(const char *uptoken, const char **pAccessKey, const char **pBucket)
23: {
24: 	// uptoken=<ak>:<signedData>:<policyDataBase64>
25: 	// extract put policy str from uptoken
26: 	// step1 decode base64
27: 	char *accessKey, *bucket;
28: 	int hitCount = 0;
29: 	int hitIndex = -1;
30: 	int len = strlen(uptoken);
31: 
32: 	for (int i = 0; i < len; i++)
33: 	{
34: 		if (uptoken[i] == ':')
35: 		{
36: 			if (hitCount == 0)
37: 			{
38: 				accessKey = Qiniu_String_Dup(uptoken);
39: 				*(accessKey + i) = '\0';
40: 			}
41: 			hitCount++;
42: 			hitIndex = i;
43: 		}
44: 	}
45: 	if ((hitCount != 2) || ((hitIndex + 1) == len))
46: 	{
47: 		Qiniu_Log_Error("invalid uptoken,should contain exactly two colon");
48: 		return Qiniu_False;
49: 	}
50: 	const char *policyB64Data = uptoken + hitIndex + 1;
51: 	char *policyData = Qiniu_String_Decode(policyB64Data);
52: 
53: 	// step2 parse json
54: 	cJSON *policy = cJSON_Parse(policyData);
55: 	const char *scope = Qiniu_Json_GetString(policy, "scope", NULL);
56: 
57: 	// step3 split bucketname from scope=<bucket>:<xx>
58: 	len = strlen(scope);
59: 	hitIndex = len;
60: 	for (int i = 0; i < len; i++)
61: 	{
62: 		if (scope[i] == ':')
63: 		{
64: 			hitIndex = i;
65: 			break;
66: 		}
67: 	}
68: 
69: 	bucket = Qiniu_String_Dup(scope);
70: 	*(bucket + hitIndex) = '\0';
71: 	cJSON_Delete(policy);
72: 	Qiniu_Free(policyData);
73: 
74: 	if (pAccessKey != NULL)
75: 	{
76: 		*pAccessKey = accessKey;
77: 	}
78: 	if (pBucket != NULL)
79: 	{
80: 		*pBucket = bucket;
81: 	}
82: 	return Qiniu_True;
83: }
